/**
 * Drawbridge brand fonts, self-hosted (production CSP allows only same-origin fonts; no Google Fonts request).
 * Latin subset woff2 files from @fontsource/poppins@5.1.0 and @fontsource/barlow@5.1.0, embedded as base64 so they
 * ship inside dist/ with no extra build or Docker step. Served by shell.ts at /app/assets/fonts/<name>.woff2.
 *
 *   Poppins: Copyright 2020 The Poppins Project Authors. Barlow: Copyright 2017 The Barlow Project Authors.
 *   Both under the SIL Open Font License 1.1 (src/platform/brand/OFL-Poppins.txt, OFL-Barlow.txt).
 *
 * SHA-256 of each file (check against the npm package to verify):
 *   poppins-500.woff2  7748 bytes  cd36de204aca2d5fa263a731f7c20009b5e3d754ba1f1e03c33e93a48f3e7446
 *   poppins-600.woff2  8000 bytes  f4e80d9dfd374d02989b87a27b5ed4cb78fbb177c27f1478e9a8b0afb7513149
 *   barlow-400.woff2  21144 bytes  7c9c80a6c32c0619d61c28f28723e68c5f8f75163e77ee5cf64c39e640e0d71e
 *   barlow-500.woff2  20960 bytes  7c0597b1b0c771139c958982210f05b275993037f0f3ba20d7a9300a0741dc80
 *   barlow-600.woff2  21796 bytes  2b14e8397d552f351a4396dec25ec5da1348865683100e94c4ab0faea4a9a254
 */
const FONTS_BASE64: Record<string, string> = {
  'poppins-500':
    '',
  'poppins-600':
    '',
  'barlow-400':
    '',
  'barlow-500':
    '',
  'barlow-600':
    '',
};

const cache = new Map<string, Buffer>();

/** The woff2 bytes of one brand font (e.g. "barlow-500"), or null for an unknown name. */
export function brandFont(name: string): Buffer | null {
  if (!Object.prototype.hasOwnProperty.call(FONTS_BASE64, name)) return null;
  let b = cache.get(name);
  if (!b) {
    b = Buffer.from(FONTS_BASE64[name], 'base64');
    cache.set(name, b);
  }
  return b;
}
